// #95ffe2 API נתוני מגמות ודשבורד — аккаунт morning: «мало дней» (few_days) и многодневный зелёный статус.
// @data: создаёт 2 еды «QA-AUTO trend <дата>» на вчера и позавчера (сегодняшний день аккаунта не трогает) и удаляет их в afterAll.
import { test, expect, BrowserContext, Page } from '@playwright/test';
import { openAs, saveSession, getTrends, ok, rest, todayIn, addDays, expectInvariants } from './_trends';

test.describe.configure({ mode: 'serial' });
// Встроенный Chromium Playwright на этой машине не запускается (context.md) — установленный Google Chrome.
test.use({ channel: 'chrome' });

const PREFIX = 'QA-AUTO trend';
// Как при перепроверке 2026-11-11: 2000/2200 kcal, 85/90 белка, 24/25 клетчатки → «green».
const NUTRIENTS = { kcal: 2000, protein: 85, fat: 60, carbs: 250, fiber: 24 };

async function cleanup(page: Page) {
  const r = await rest(page, 'DELETE', `rest/v1/meals?title=like.${encodeURIComponent(PREFIX + '*')}&select=id`);
  expect(r.status, `удаление ${PREFIX}*: ${JSON.stringify(r.body).slice(0, 200)}`).toBe(200);
}

test.describe('trends API — morning, мало данных за период', () => {
  let ctx: BrowserContext;
  let page: Page;
  let today: string;
  let d1: string; // вчера
  let d2: string; // позавчера

  test.beforeAll(async ({ browser }) => {
    ({ ctx, page } = await openAs(browser, 'morning'));
    today = await todayIn(page);
    d1 = addDays(today, -1);
    d2 = addDays(today, -2);
    await cleanup(page); // остатки прошлого упавшего прогона
  });
  test.afterAll(async () => {
    if (!ctx) return;
    try {
      await cleanup(page);
      const left = await rest(page, 'GET', `rest/v1/meals?select=id&title=like.${encodeURIComponent(PREFIX + '*')}`);
      expect(left.body, `после чистки не осталось ${PREFIX}*`).toEqual([]);
    } finally {
      await saveSession(ctx, page, 'morning');
    }
  });

  test('2 дня данных: неделя/месяц → few_days без home, custom 2 дня → enough, статусы green #95ffe2 @data', async () => {
    // Предусловие: за прошлые 6 дней недели у morning нет еды (иначе порог недели не проверить).
    const base = ok(await getTrends(page, { kind: 'week' }), 'week до');
    expect(base.daysWithData, 'предусловие: у morning нет еды в прошлые дни недели').toBe(0);

    for (const date of [d2, d1]) {
      await page.evaluate(
        async ({ title, date, nutrients }) => {
          await (window as any).__qaApi.balance.logMeal({ title, date, time: '12:00', nutrients });
        },
        { title: `${PREFIX} ${date}`, date, nutrients: NUTRIENTS },
      );
    }
    // Дождаться, что view видит обе записи.
    await expect
      .poll(async () => (await rest(page, 'GET', `rest/v1/daily_totals?select=local_date&local_date=gte.${d2}&local_date=lte.${d1}`)).body.length, {
        message: 'daily_totals показывает 2 созданных дня',
      })
      .toBe(2);

    // AC7: неделя (порог 3 дня) и месяц (порог 7) — индикатор few_days, home пуст; сегодняшний день не считается.
    for (const kind of ['week', 'month']) {
      const t = ok(await getTrends(page, { kind }), kind);
      expectInvariants(t, `morning/${kind}`);
      expect(t.daysWithData, `${kind}: дней с данными`).toBe(2);
      expect(t.enoughData, `${kind}: enoughData`).toBe(false);
      expect(t.notEnoughReason, `${kind}: причина`).toBe('few_days');
      expect(t.home, `${kind}: home`).toEqual([]);
    }

    // AC1/AC3/AC4/AC5: custom вчера-позавчера (порог 2) — достаточно данных, среднее против цели, green.
    const c = ok(await getTrends(page, { kind: 'custom', from: d2, to: d1 }), 'custom 2 дня');
    expectInvariants(c, 'morning/custom2');
    expect(c.range).toMatchObject({ kind: 'custom', from: d2, to: d1, days: 2 });
    expect(c.daysWithData).toBe(2);
    expect(c.minDays).toBe(2);
    expect(c.enoughData).toBe(true);
    expect(c.metrics.map((m) => [m.key, m.value, m.target, m.status])).toEqual([
      ['kcal', 2000, 2200, 'green'],
      ['protein', 85, 90, 'green'],
      ['fiber', 24, 25, 'green'],
    ]);
    expect(c.home).toEqual([
      { key: 'kcal', status: 'green' },
      { key: 'protein', status: 'green' },
    ]);
  });
});
